	"testing"

	"github.com/luwa07832/vuln-registry/internal/store"
)

func validUpdateBody() map[string]any {
	return map[string]any{
		"component": "openssl",
		"affected_ranges": []map[string]any{
			{"lower": "3.0.0", "lower_include": true, "upper": "3.1.0", "upper_include": true},
			{"upper": "1.0.0", "upper_include": false},
		},
		"severity":      "critical",
		"fixed_version": "3.1.1",
		"status":        "fixed",
	}
}

func putVulnerability(t *testing.T, router http.Handler, id string, body any) *httptest.ResponseRecorder {
	t.Helper()
	return doJSON(t, router, http.MethodPut, "/vulnerabilities/"+id, body)
}

func assertInvalidInput(t *testing.T, recorder *httptest.ResponseRecorder) {
	t.Helper()
	if recorder.Code != http.StatusBadRequest || recorder.Body.String() != "error=INVALID_INPUT" {
		t.Fatalf("status=%d body=%q", recorder.Code, recorder.Body.String())
	}
}

func TestUpdateVulnerabilitySuccess(t *testing.T) {
	router := newTestRouter(t)
	registerVulnerability(t, router, validCreateBody("CVE-2024-1001"))

	body := validUpdateBody()
	recorder := putVulnerability(t, router, "CVE-2024-1001", body)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}

	var record struct {
		ID        string `json:"id"`
		Component string `json:"component"`
		Ranges    []struct {
			Lower        *string `json:"lower"`
			LowerInclude *bool   `json:"lower_include"`
			Upper        *string `json:"upper"`
			UpperInclude *bool   `json:"upper_include"`
		} `json:"affected_ranges"`
		Severity     string `json:"severity"`
		FixedVersion string `json:"fixed_version"`
		Status       string `json:"status"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &record); err != nil {
		t.Fatalf("unmarshal: %v body=%s", err, recorder.Body.String())
	}
	if record.ID != "CVE-2024-1001" || record.Component != "openssl" ||
		record.Severity != "critical" || record.FixedVersion != "3.1.1" || record.Status != "fixed" {
		t.Fatalf("scalar fields wrong: %#v", record)
	}
	if len(record.Ranges) != 2 {
		t.Fatalf("ranges = %d, want 2", len(record.Ranges))
	}
	if record.Ranges[0].Lower == nil || *record.Ranges[0].Lower != "3.0.0" ||
		record.Ranges[0].Upper == nil || *record.Ranges[0].Upper != "3.1.0" ||
		record.Ranges[0].LowerInclude == nil || !*record.Ranges[0].LowerInclude ||
		record.Ranges[0].UpperInclude == nil || !*record.Ranges[0].UpperInclude {
		t.Fatalf("first range wrong: %#v", record.Ranges[0])
	}
	if record.Ranges[1].Lower != nil || record.Ranges[1].LowerInclude != nil {
		t.Fatalf("open lower bound must serialize as null: %#v", record.Ranges[1])
	}
	if record.Ranges[1].Upper == nil || *record.Ranges[1].Upper != "1.0.0" ||
		record.Ranges[1].UpperInclude == nil || *record.Ranges[1].UpperInclude {
		t.Fatalf("second range wrong: %#v", record.Ranges[1])
	}
}

func TestUpdateVulnerabilityPersistsAndIDStays(t *testing.T) {
	router := newTestRouter(t)
	registerVulnerability(t, router, validCreateBody("CVE-2024-1002"))

	if recorder := putVulnerability(t, router, "CVE-2024-1002", validUpdateBody()); recorder.Code != http.StatusOK {
		t.Fatalf("update status = %d body = %s", recorder.Code, recorder.Body.String())
	}

	// The old id still resolves to the replaced content.
	fetched := doJSON(t, router, http.MethodGet, "/vulnerabilities/CVE-2024-1002", nil)
	if fetched.Code != http.StatusOK {
		t.Fatalf("get status = %d body = %s", fetched.Code, fetched.Body.String())
	}
	var record map[string]any
	if err := json.Unmarshal(fetched.Body.Bytes(), &record); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if record["component"] != "openssl" || record["severity"] != "critical" ||
		record["fixed_version"] != "3.1.1" || record["status"] != "fixed" {
		t.Fatalf("stored scalar fields wrong: %v", record)
	}
	ranges := record["affected_ranges"].([]any)
	if len(ranges) != 2 || ranges[1].(map[string]any)["lower"] != nil {
		t.Fatalf("stored ranges wrong: %v", ranges)
	}

	// Old component no longer matches; the new component drives queries.
	old := doJSON(t, router, http.MethodGet,
		"/vulnerabilities/affected?component=libxml2&version=2.4.1", nil)
	var oldHits []map[string]any
	if err := json.Unmarshal(old.Body.Bytes(), &oldHits); err != nil {
		t.Fatalf("unmarshal old: %v", err)
	}
	if len(oldHits) != 0 {
		t.Fatalf("old component must no longer match: %v", oldHits)
	}
	newHitsRecorder := doJSON(t, router, http.MethodGet,
		"/vulnerabilities/affected?component=openssl&version=3.0.5", nil)
	var newHits []map[string]any
	if err := json.Unmarshal(newHitsRecorder.Body.Bytes(), &newHits); err != nil {
		t.Fatalf("unmarshal new: %v", err)
	}
	if len(newHits) != 1 || newHits[0]["id"] != "CVE-2024-1002" || newHits[0]["status"] != "fixed" {
		t.Fatalf("new component query wrong: %v", newHits)
	}

	// New status is visible through the list filter.
	filtered := doJSON(t, router, http.MethodGet, "/vulnerabilities?component=openssl&status=fixed", nil)
	var page struct {
		Items []map[string]any `json:"items"`
		Total int              `json:"total"`
	}
	if err := json.Unmarshal(filtered.Body.Bytes(), &page); err != nil {
		t.Fatalf("unmarshal list: %v", err)
	}
	if page.Total != 1 || len(page.Items) != 1 || page.Items[0]["id"] != "CVE-2024-1002" {
		t.Fatalf("filtered list wrong: %+v", page)
	}
}

